function refreshFormat(){
    const fs=$('filesystem').value||'fat32',select=$('cluster-size'),previous=Number(select.value||0);
    const extra=['udf','hfsplus','apfs','btrfs','xfs'].includes(fs);
    const choices=(extra||fs.indexOf('ext')===0||fs==='f2fs')?[0]:[0,1,2,4,8,16,32,64].concat(fs==='ntfs'?[128]:fs==='exfat'?[128,256,512,1024,2048,4096,8192,16384,32768,65536]:[]);
    select.innerHTML=choices.map(n=>`<option value="${n}">${n?n*512+' '+t('bytes','بايت'):t('Automatic','تلقائي')}</option>`).join('')+(choices.length>1?`<option value="custom">${t('Custom — type bytes','مخصص — اكتب البايتات')}</option>`:'');select.value=String(choices.includes(previous)?previous:0);select.disabled=extra||fs.indexOf('ext')===0||fs==='f2fs';
    const table=$('partition-table');if(fs==='apfs')table.value='gpt';table.disabled=fs==='apfs';$('volume-label').maxLength=fs==='xfs'?12:extra?15:32;customCluster();enhanceChoices();
}
function customCluster(){const custom=$('cluster-size').value==='custom'&&!$('cluster-size').disabled;const field=$('custom-cluster-bytes');field.hidden=!custom;field.disabled=!custom;$('custom-cluster-label').hidden=!custom;}
function targetText(){const d=state.devices.find(d=>d.id===state.selected);return d?`${esc(d.name)} · ${esc(d.vendor)}`:t('No USB selected. Connect and authorize a drive first.','لم يُحدد USB. صل وحدة وامنح الإذن أولاً.');}
