ERRORS.FS_GEOMETRY=['This filesystem uses an unsupported sector/block layout. No repair was started.','يستخدم نظام الملفات تخطيط قطاعات أو كتل غير مدعوم. لم يبدأ الإصلاح.'];
ERRORS.FSUSB_INTERNAL=['For direct USB filesystem extraction, choose a folder in this device’s internal storage. This prevents accidental output onto the source USB.','للاستخراج المباشر من نظام ملفات USB اختر مجلداً في التخزين الداخلي لهذا الجهاز، لمنع الكتابة العرضية إلى USB المصدر.'];
ERRORS.FSIMAGE_KIND=['Choose an NTFS or ext2/3/4 filesystem image partition. Use the separate FAT image browser for FAT16/32.','اختر قسم صورة نظام NTFS أو ext2/3/4. استخدم متصفح FAT المنفصل لصور FAT16/32.'];
ERRORS.FSIMAGE_ENGINE_FAILED=['The image could not be read safely. It may be damaged, need journal recovery, use unsupported features, exceed limits or have an I/O error. No source repair or OS mount was attempted.','تعذرت قراءة الصورة بأمان. ربما هي تالفة أو تحتاج استعادة السجل أو تستخدم ميزات غير مدعومة أو تتجاوز الحدود أو حدث خطأ قراءة. لم تُحاول تهيئة المصدر أو إصلاحه أو تركيبه في النظام.'];
ERRORS.ZERO_MISMATCH=['Nonzero data was found. This is expected on normally formatted drives; this tool checks only a drive you intended to zero-fill. It does not mean the drive is damaged. Details show the sector and byte offset.','عُثر على بيانات غير صفرية. هذا متوقع على الوحدات المهيأة بصورة عادية؛ تفحص الأداة وحدة قصدت ملأها بالأصفار فقط. لا يعني ذلك تلف الوحدة. تعرض التفاصيل القطاع وإزاحة البايت.'];
ERRORS.DISK_GEOMETRY=['The reported disk geometry cannot be scanned safely.','لا تسمح هندسة القرص المبلّغ عنها بفحص آمن.'];
ERRORS.CHD_CREATE_OPTIONS=['Use a nonempty raw file aligned to512 or2048 bytes within the selected limit (up to16 GiB). Stored CHD creation does not compress data or reconstruct CD tracks.','استخدم ملفاً خاماً غير فارغ بمحاذاة512 أو2048 بايت ضمن الحد المختار (حتى16 GiB). إنشاء CHD دون ضغط لا يضغط البيانات ولا يعيد بناء مسارات CD.'];
ERRORS.CHD_ENGINE_FAILED=['CHD decoding failed. This tool requires standalone CHDv5 hard-disk/DVD data with 512/2048-byte units within the selected size limit. Parent-dependent, CD multi-track, unsupported codecs, oversized hunks, damaged files or I/O failures are rejected.','فشل فك CHD. تتطلب الأداة بيانات قرص أو DVD مستقلة من CHDv5 بوحدات 512/2048 بايت وضمن الحد المختار. ترفض الصور التابعة لأصل وأقراص CD متعددة المسارات والترميزات غير المدعومة والكتل الكبيرة والملفات التالفة وأخطاء الإدخال والإخراج.'];
ERRORS.CHD_METADATA=['The CHD geometry or decoded output set did not match the validated source.','لم تطابق هندسة CHD أو مجموعة الناتج المصدر الذي فُحص.'];
ERRORS.ARCHIVE_ENGINE_FAILED=['Archive validation/extraction failed: the file may be damaged, encrypted, split, use an unsupported codec, exceed the selected limit or have an I/O error. Read details; no source was changed.','فشل فحص الأرشيف أو استخراجه: ربما الملف تالف أو مشفر أو مقسم أو يستخدم ترميزاً غير مدعوم أو يتجاوز الحد المختار أو حدث خطأ إدخال وإخراج. راجع التفاصيل؛ لم يتغير المصدر.'];
ERRORS.ARCHIVE_PASSWORD=['Enter a password up to256 characters without null characters. Supported encrypted archives: traditional ZIP only.','أدخل كلمة مرور حتى٢٥٦ حرفاً دون محارف فارغة. الأرشيفات المشفرة المدعومة: ZIP التقليدي فقط.'];
ERRORS.ARCHIVE_PATH=['The archive has unsafe, conflicting, malformed or linked paths. Nothing is extracted into existing folders.','يحتوي الأرشيف مسارات خطرة أو متعارضة أو غير صالحة أو روابط. لا يستخرج إلى مجلدات موجودة.'];
ERRORS.ARCHIVE_LIMIT=['Use a supported size limit; archives allow up to 10,000 entries and 16 GiB expanded data. Decoder dictionaries are capped at 128 MiB.','اختر حد حجم مدعوماً؛ تسمح الأرشيفات حتى ١٠٬٠٠٠ إدخال و16 GiB بعد الفك. حد قواميس مفكك الترميز 128 MiB.'];
ERRORS.ARCHIVE_MANIFEST=['The archive metadata could not be validated safely.','تعذر التحقق من بيانات الأرشيف الوصفية بأمان.'];
ERRORS.ARCHIVE_CHANGED=['The source or extracted file set changed during processing. The new output is not accepted.','تغير المصدر أو مجموعة الملفات أثناء المعالجة. لا يعتمد الناتج الجديد.'];
ERRORS.DMG_HEADER=['Choose a supported XML UDIF DMG with a valid koly footer.','اختر DMG من نوع XML UDIF المدعوم وتذييل koly صالح.'];
ERRORS.DMG_UNSUPPORTED=['This DMG uses unsupported encryption, segmentation, compression or checksum features. Raw/zero/ADC/zlib single-segment XML UDIF images are supported.','يستخدم DMG تشفيراً أو تجزئة أو ضغطاً أو بصمات غير مدعومة. تدعم الأداة XML UDIF أحادي الجزء بكتل خام أو أصفار أو ADC أو zlib.'];
ERRORS.DMG_BOUNDS=['The DMG block map, size, metadata or offsets are invalid, overlapping or exceed the selected limit.','خريطة كتل DMG أو الحجم أو البيانات الوصفية أو الإزاحات غير صالحة أو متداخلة أو تتجاوز الحد المختار.'];
ERRORS.DMG_PLIST=['The XML UDIF metadata is invalid or unsupported. External entities are not loaded.','بيانات XML UDIF غير صالحة أو غير مدعومة. لا تُحمّل كيانات خارجية.'];
ERRORS.DMG_DATA=['A DMG block is damaged, truncated or has an unexpected decoded size.','كتلة DMG تالفة أو ناقصة أو لا يطابق حجمها بعد الفك المتوقع.'];
ERRORS.DMG_CHECKSUM=['A DMG block-table CRC32 did not match. Keep the original and obtain an intact source.','لم تتطابق CRC32 لخريطة كتل DMG. احتفظ بالأصل واحصل على مصدر سليم.'];
ERRORS.FS_REPAIR_ISSUES=['Repair or its follow-up check did not complete cleanly. Metadata may have changed. Keep your backup and use suitable computer tools for severe errors; do not repeatedly repair or format needed data.','لم يكتمل الإصلاح أو الفحص اللاحق بنجاح. ربما تغيرت البيانات الوصفية. احتفظ بنسختك واستخدم أدوات الحاسوب المناسبة للأخطاء الشديدة؛ لا تكرر إصلاح أو تهيئة بيانات مطلوبة.'];
ERRORS.FS_CHECK_ISSUES=['The read-only check reported filesystem issues or could not complete. Review details and keep backups before repair.','أبلغ الفحص للقراءة عن مشكلات في نظام الملفات أو تعذر إكماله. راجع التفاصيل واحتفظ بنسخ احتياطية قبل الإصلاح.'];
ERRORS.ZSO_DATA=['A ZSO/LZ4 block is malformed, truncated or cannot expand to exactly2048 bytes.','كتلة ZSO/LZ4 غير صالحة أو ناقصة أو لا يمكن فكها إلى2048 بايت بالضبط.'];
ERRORS.CONSOLE_OPTIONS=['Choose a nonempty file up to64 GiB and at most64 parts. ISO.# needs2048-byte sector alignment; use .666NN for other files.','اختر ملفاً غير فارغ بحد64 GiB و64 جزءاً. يحتاج ISO.# محاذاة2048 بايت؛ استخدم .666NN للملفات الأخرى.'];
ERRORS.CONSOLE_NAME=['Use a short safe filename without path separators or reserved characters. ISO.# output names must end .iso.','استخدم اسماً قصيراً آمناً دون فواصل مسار أو رموز محجوزة. يجب أن ينتهي اسم ISO.# بـ.iso.'];
ERRORS.CONSOLE_MANIFEST=['Select the original .usbwb manifest made by this tool together with ALL parts. The manifest is missing, changed or invalid. Third-party sets need their own tool.','حدد ملف .usbwb الأصلي الذي أنشأته الأداة مع كل الأجزاء. ملف التحقق مفقود أو معدل أو غير صالح. تحتاج مجموعات البرامج الأخرى أدواتها الخاصة.'];
ERRORS.CONSOLE_PARTS=['Select exactly the numbered files listed in the manifest, with no missing, renamed, duplicate or unrelated files.','حدد الأجزاء المرقمة المطابقة لملف التحقق دون أجزاء مفقودة أو معاد تسميتها أو مكررة أو ملفات غير مرتبطة.'];
ERRORS.CONSOLE_PART_SIZE=['A part has an unknown or incorrect size, or its data ended early. Use complete local files.','حجم أحد الأجزاء غير معروف أو غير صحيح أو انتهت بياناته مبكراً. استخدم ملفات محلية كاملة.'];
ERRORS.CONSOLE_PART_CORRUPT=['A numbered part does not match the saved SHA-256. Replace the damaged part from your original source.','لا يطابق جزء مرقم بصمة SHA-256 المحفوظة. استبدل الجزء التالف من مصدرك الأصلي.'];
ERRORS.CONSOLE_PROVIDER=['The selected storage provider changed an output filename. Choose a local folder that preserves the requested names.','غيّر مزود التخزين اسم ملف الناتج. اختر مجلداً محلياً يحافظ على الأسماء المطلوبة.'];
ERRORS.FAT_IMAGE_PARTITION=['Select0 for a raw FAT volume or a valid FAT partition number (MBR1–4/GPT1–128). GPT tables must pass CRC validation.','اختر0 لوحدة FAT خام أو رقم قسم FAT صالح (MBR من1 إلى4 وGPT من1 إلى128). يجب أن تنجح فحوص CRC لجداول GPT.'];
ERRORS.FAT_IMAGE_BPB=['The selected volume has invalid FAT16/32 geometry or unsupported sector size. Choose the correct partition.','هندسة FAT16/32 للوحدة المختارة غير صالحة أو حجم القطاع غير مدعوم. اختر القسم الصحيح.'];
ERRORS.FAT_IMAGE_UNSUPPORTED=['This reader supports FAT16/32 with 512-byte sectors and up to32 million clusters. FAT12/exFAT/NTFS/ext require other readers.','يدعم القارئ FAT16/32 بقطاع 512 بايت وبحد32 مليون عنقود. تحتاج FAT12 وexFAT وNTFS وext قراءً آخرين.'];
ERRORS.FAT_IMAGE_CHAIN=['An allocated chain is cyclic, shared, incomplete or outside the volume. No source repair is attempted.','سلسلة تخصيص دائرية أو مشتركة أو ناقصة أو خارج الوحدة. لا يحاول التطبيق إصلاح المصدر.'];
ERRORS.FAT_IMAGE_NAME=['A filename/long-name sequence is unsafe or unsupported. This reader supports Unicode long names and ASCII short names.','اسم ملف أو تسلسل أسماء طويلة غير آمن أو غير مدعوم. يدعم القارئ أسماء Unicode الطويلة وASCII القصيرة.'];
ERRORS.COMPRESSED_DATA=['The compressed stream is damaged, incomplete, unreadable or does not match the selected GZIP/XZ mode. Check the file and its publisher checksum.','التدفق المضغوط تالف أو ناقص أو لا يمكن قراءته أو لا يطابق وضع GZIP/XZ المختار. تحقق من الملف وبصمة ناشره.'];
ERRORS.XZ_MEMORY_LIMIT=['This XZ stream requires more than the32 MiB decoder-memory limit. Unpack it on another device or use a compatible stream.','يحتاج تدفق XZ ذاكرة فك تزيد على حد32 MiB. فكه على جهاز آخر أو استخدم تدفقاً متوافقاً.'];
ERRORS.CONVERT_LIMIT=['The image exceeds the selected limit (maximum16 GiB), is empty, or has an invalid size. Choose an appropriate limit and check the input.','تتجاوز الصورة الحد المختار (أقصاه16 GiB) أو أنها فارغة أو ذات حجم غير صالح. اختر حداً مناسباً وتحقق من المصدر.'];
ERRORS.CSO_ISO=['Choose a complete sector-aligned ISO9660 image with a primary volume descriptor.','اختر صورة ISO9660 كاملة بمحاذاة القطاعات وتحتوي واصف الوحدة الرئيسي.'];
ERRORS.CSO_UNSUPPORTED=['Choose the matching CSO or ZSO tool: version1,2048-byte blocks, index shift0–12. CSOv2/other block sizes are unsupported.','اختر أداة CSO أو ZSO المطابقة: الإصدار1 وكتل2048 بايت وإزاحة فهرس0–12. لا تُدعم CSOv2 أو أحجام الكتل الأخرى.'];
ERRORS.CSO_HEADER=['The CSO header or original size is invalid.','ترويسة CSO أو الحجم الأصلي غير صالح.'];
ERRORS.CSO_INDEX=['The CSO index is truncated, overlaps metadata, or points outside valid block data.','فهرس CSO ناقص أو يتداخل مع البيانات الوصفية أو يشير خارج بيانات الكتل الصالحة.'];
ERRORS.CSO_DATA=['A CSO block is corrupt or cannot be expanded to exactly2048 bytes.','كتلة CSO تالفة أو لا يمكن فكها إلى2048 بايت بالضبط.'];
ERRORS.CSO_DEFLATE=['The compression engine could not finish a CSO block.','تعذر على محرك الضغط إكمال كتلة CSO.'];
ERRORS.IMAGE_SEEK_REQUIRED=['Choose a complete local image that supports random access. Streaming/cloud-only providers cannot be used for ISO/WIM browsing.','اختر صورة محلية كاملة تدعم الوصول العشوائي. لا يمكن استخدام مزود تدفق أو ملف سحابي فقط لتصفح ISO/WIM.'];
ERRORS.WINDOWS_USB_ROOT=['Choose the root of an empty removable USB in the folder picker, not phone storage or a subfolder. Confirm FAT32 yourself.','اختر جذر USB قابل للإزالة وفارغاً بمنتقي المجلدات، وليس تخزين الهاتف أو مجلداً فرعياً. تحقق من FAT32 بنفسك.'];
ERRORS.WINDOWS_EMPTY_ROOT=['The USB root is not empty. Back up or move its files yourself, then choose an empty FAT32 USB root. Nothing is overwritten.','جذر USB ليس فارغاً. انسخ ملفاته أو انقلها بنفسك ثم اختر جذر USB فارغاً بنظام FAT32. لا تُستبدل الملفات.'];
ERRORS.FAT32_FILE_LIMIT=['A file exceeds FAT32’s limit. Large install.wim can be split, but other oversized files/ESD need a different supported image.','يتجاوز ملف حد FAT32. يمكن تقسيم install.wim الكبير، لكن الملفات الأخرى أو ESD الكبيرة تحتاج صورة أخرى مدعومة.'];
ERRORS.WIM_ENGINE_FAILED=['The WIM engine rejected the image or could not finish. Open details for its exact reason; solid/ESD and oversized individual resources may not split. Folder export allows 1,000 regular files/10,000 paths; select a smaller valid subtree if needed.','رفض محرك WIM الصورة أو تعذر إكمال العملية. افتح التفاصيل للسبب الدقيق؛ قد لا تُقسم ESD والصور ذات الضغط الصلب والموارد الفردية الكبيرة جداً. يسمح تصدير المجلد بـ١٬٠٠٠ ملف عادي و١٠٬٠٠٠ مسار؛ اختر مجلداً فرعياً أصغر صالحاً عند الحاجة.'];
ERRORS.VENTOY_SIZE=['Initial Ventoy installation requires512-byte sectors and at least128 MiB, within the32-bit USB address range.','يتطلب تثبيت Ventoy الأولي قطاع 512 بايت وسعة128 MiB على الأقل ضمن مجال عناوين USB ذي32 بت.'];
ERRORS.VENTOY_PACKAGE=['Choose the official Ventoy Linux tar.gz package and verify its publisher SHA-256. Required data is missing, unsupported or damaged.','اختر حزمة Ventoy Linux الرسمية بصيغة tar.gz وتحقق من SHA-256 المنشورة. البيانات المطلوبة مفقودة أو غير مدعومة أو تالفة.'];
ERRORS.VENTOY_ASSET_CHANGED=['Imported Ventoy data changed or is incomplete. Import a verified official package again before installation. No USB write starts until this check passes.','تغيرت بيانات Ventoy المستوردة أو كانت ناقصة. أعد استيراد حزمة رسمية متحقق منها قبل التثبيت. لا تبدأ كتابة USB قبل نجاح الفحص.'];
ERRORS.TARGET_PHONE_ONLY=['Save this new file in internal phone/tablet storage, such as Downloads. A USB or cloud destination is not allowed for this action.','احفظ الملف الجديد على تخزين الهاتف أو الجهاز اللوحي الداخلي مثل التنزيلات. لا يسمح هذا الإجراء بوجهة USB أو سحابية.'];
ERRORS.TABLE_NO_ROOM=['The layout has insufficient reserved space for a safe table conversion. This tool does not shrink or move filesystems. Back up files and use a suitable layout.','لا يترك التخطيط مساحة محجوزة كافية لتحويل الجدول بأمان. لا تصغّر هذه الأداة أنظمة الملفات ولا تنقلها. انسخ الملفات واستخدم تخطيطاً مناسباً.'];
ERRORS.TABLE_ALREADY=['The drive already uses the selected partition-table type. No conversion is needed.','تستخدم الوحدة نوع جدول الأقسام المحدد بالفعل. لا تحتاج إلى تحويل.'];
ERRORS.TABLE_TOO_MANY=['MBR conversion supports at most four primary partitions. No conversion started.','يدعم التحويل إلى MBR أربعة أقسام أولية على الأكثر. لم يبدأ التحويل.'];
ERRORS.TABLE_UNSUPPORTED=['This partition layout/type is outside the converter’s supported basic layouts. Nothing was converted.','تخطيط أو نوع الأقسام خارج التخطيطات البسيطة التي يدعمها المحول. لم يُحول شيء.'];
ERRORS.TABLE_ENCRYPTED=['A recognized encrypted volume was detected. This converter does not support it.','اكتُشفت وحدة مشفرة معروفة. لا يدعمها هذا المحول.'];
ERRORS.VENTOY_UPDATE_LAYOUT=['Choose an existing recognized MBR Ventoy drive. GPT, custom and unknown boot layouts are not supported by this updater.','اختر وحدة Ventoy موجودة ومعروفة بجدول MBR. لا يدعم هذا المحدث GPT أو تخطيطات الإقلاع المخصصة أو المجهولة.'];
ERRORS.PERSISTENCE_OPTIONS=['Enter a whole size from256 to16384 MiB and a1–16-character ASCII label (letters, digits, _ or -). Check the distro-required label.','أدخل حجماً صحيحاً من256 إلى16384 MiB واسماً من1 إلى16 حرفاً لاتينياً أو رقماً أو _ أو -. راجع الاسم المطلوب لتوزيعتك.'];
ERRORS.PERSISTENCE_ISO_PATH=['Enter the exact .iso path on the Ventoy data partition, such as /ISO/Linux.iso.','أدخل مسار .iso الدقيق على قسم بيانات Ventoy مثل /ISO/Linux.iso.'];
ERRORS.WIM_INDEX=['Enter an image index from1to256 that exists in your WIM.','أدخل رقم صورة من1 إلى 256 موجوداً داخل WIM الخاص بك.'];
ERRORS.WIM_FILE_PATH=['Choose a listed WIM path, or replace the entire field with /folder/file.txt. Do not add a blank path component. Use WIM folder export for directories.','اختر مساراً من القائمة أو استبدل الحقل كاملاً بـ /folder/file.txt دون أجزاء فارغة. استخدم تصدير مجلد WIM للمجلدات.'];
ERRORS.BENCH_CLEANUP=['The provider could not remove the new benchmark file. Remove only the named temporary file shown in details.','تعذر على المزود حذف ملف الاختبار الجديد. احذف الملف المؤقت المذكور في التفاصيل فقط.'];
ERRORS.NTFS_BOOT_INVALID=ERRORS.NTFS_BACKUP_INVALID=ERRORS.NTFS_MFT_INVALID=['NTFS structural verification failed. The drive may be incomplete; its partition table was not committed. Open details for the stage and settings.','فشل التحقق من بنية NTFS. قد تكون الوحدة غير مكتملة؛ لم يُعتمد جدول أقسامها. افتح التفاصيل للمرحلة والإعدادات.'];


JOB_NAMES.wimTreeList=['Browse WIM folder','تصفح مجلد WIM'];JOB_NAMES.wimTreeExtract=['Export WIM folder','تصدير مجلد WIM'];JOB_NAMES.ulCreate=['Create USBExtreme files','إنشاء ملفات USBExtreme'];JOB_NAMES.ulInspect=['Inspect ul.cfg','فحص ul.cfg'];
ERRORS.UL_OPTIONS=['Use a sector-aligned PS2 ISO up to16 GiB, CD/DVD media, a valid disc ID and a1–32-character printable ASCII title without surrounding spaces.','استخدم PS2 ISO بمحاذاة القطاعات حتى16 GiB ونوع CD/DVD ورقم قرص صالح وعنوان ASCII قابل للطباعة من١ إلى٣٢ رمزاً دون مسافات طرفية.'];
ERRORS.UL_SYSTEM=['The ISO must contain a supported root SYSTEM.CNF with one BOOT2 cdrom path and disc ID such as SLUS_123.45. Raw BIN, encrypted/non-PS2 images and ambiguous boot entries are unsupported.','يجب أن تحتوي ISO على SYSTEM.CNF مدعوم في الجذر مع مسار BOOT2 cdrom واحد ورقم قرص مثل SLUS_123.45. لا تدعم BIN الخام أو الصور المشفرة أو غير الخاصة بـPS2 أو إدخالات الإقلاع الملتبسة.'];
ERRORS.UL_CFG=['Choose a valid standard ul.cfg with up to1000 unique entries, ASCII titles and supported disc IDs/media/part counts. This is catalog inspection only.','اختر ul.cfg قياسياً صالحاً حتى١٠٠٠ إدخال فريد وعناوين ASCII وأرقام وأنواع وأعداد أجزاء مدعومة. هذا فحص للفهرس فقط.'];

JOB_NAMES.readMap=['Read-error map','خريطة أخطاء القراءة'];JOB_NAMES.readMapShow=['Saved read-error map','خريطة أخطاء القراءة المحفوظة'];
ERRORS.READ_MAP_OPTIONS=['This map supports512-byte sectors and drives up to2 TiB. Choose New, Resume or Show saved map.','تدعم الخريطة قطاع512بايت ووحدات حتى2 TiB. اختر جديداً أو استكمالاً أو عرض المحفوظ.'];
ERRORS.READ_MAP_MISSING=['No saved checkpoint is available. Start a new read-only map first.','لا توجد نقطة استكمال محفوظة. ابدأ خريطة قراءة جديدة أولاً.'];
ERRORS.READ_MAP_RECORD=['The checkpoint is invalid or incomplete. It cannot be resumed; a new map replaces that saved record only.','نقطة الاستكمال غير صالحة أو غير مكتملة ولا يمكن استكمالها؛ تستبدل الخريطة الجديدة السجل المحفوظ فقط.'];
ERRORS.READ_MAP_IDENTITY=['The selected drive does not match the saved geometry/sampled identity. Resume was refused. Choose the original unchanged drive or start a new map.','لا تطابق الوحدة الهندسة أو الهوية المأخوذة من العينات. رُفض الاستكمال. اختر الوحدة الأصلية دون تغيير أو ابدأ خريطة جديدة.'];
ERRORS.READ_MAP_PAUSED=['A read request failed and its range was recorded. Progress was saved. Reconnect and review Resume to continue AFTER that range; this is not repair or proof every sector is bad.','فشل طلب قراءة وسُجل نطاقه وحُفظ التقدم. أعد التوصيل وراجع الاستكمال للمتابعة بعده؛ ليس إصلاحاً أو إثباتاً لتلف كل قطاع.'];
ERRORS.READ_MAP_LIMIT=['The4096range limit was reached. The saved checkpoint remains available; no repair was attempted.','بُلغ حد4096نطاقاً. تبقى نقطة الاستكمال متاحة ولم تُحاول أية إصلاحات.'];
ERRORS.READ_MAP_SAVE=['Could not verify the saved checkpoint. Free internal storage and inspect saved progress before resuming.','تعذر التحقق من حفظ نقطة الاستكمال. وفر مساحة داخلية وافحص التقدم المحفوظ قبل المتابعة.'];

ERRORS.ISO_PERSISTENCE_LAYOUT=['This direct-persistence mode needs a supported bootable MBR ISO9660 hybrid image with a free primary partition entry. No ISO writes were made during this layout check.','يحتاج وضع الاستمرار المباشر ISO9660 هجينة قابلة للإقلاع بجدول MBR مدعوم وخانة قسم أولي فارغة. لم يكتب فحص التخطيط بيانات ISO.'];
ERRORS.ISO_PERSISTENCE_GPT=['GPT/protective ISO layouts are not supported for direct persistence. The layout check stops before writing; ordinary raw image writing remains separate.','لا يدعم الاستمرار المباشر صور GPT أو الجداول الواقية. يتوقف الفحص قبل الكتابة؛ تبقى كتابة الصورة الخام مساراً منفصلاً.'];
ERRORS.ISO_PERSISTENCE_SPACE=['Not enough USB space after the ISO and its declared partitions for this custom size. Nothing was written during this check.','لا تكفي مساحة USB بعد ISO وأقسامها للحجم المخصص. لم يكتب هذا الفحص شيئاً.'];
ERRORS.ISO_PERSISTENCE_GEOMETRY=['Direct persistence requires 512-byte sectors and a drive smaller than 2 TiB. The layout check made no writes.','يحتاج الاستمرار المباشر قطاع512 بايت ووحدة أصغر من2 TiB. لم يكتب فحص التخطيط شيئاً.'];
ERRORS.ISO_PERSISTENCE_INCOMPLETE=['The drive may be partly written or its partition entry incomplete. Stop and keep View details; do not blindly retry or unplug while work is active.','ربما كُتبت الوحدة جزئياً أو لم تكتمل خانة قسمها. توقف واحتفظ بالتفاصيل؛ لا تعد المحاولة عشوائياً ولا تفصل الكابل أثناء العمل.'];
function errorText(raw){const key=String(raw).split(/[ @]/)[0];if(ERRORS[key])return pair(ERRORS[key]);if(key==='NOT_TAR'||key.startsWith('TAR_'))return t('This TAR archive is unsupported, unsafe, damaged or beyond the stated limits. Open details for the exact check that failed.','أرشيف TAR غير مدعوم أو غير آمن أو تالف أو يتجاوز الحدود الموضحة. افتح التفاصيل لمعرفة الفحص الذي فشل.');if(key==='NOT_ISO'||key.startsWith('ISO_')||key.startsWith('UDF_')||key.startsWith('IMAGE_'))return t('The image layout is unsupported, damaged or outside the safety limits. This does not mean the phone cannot use USB. Open details.','تخطيط الصورة غير مدعوم أو تالف أو خارج حدود الأمان. هذا لا يعني أن الهاتف لا يستطيع استخدام USB. افتح التفاصيل.');if(key==='NOT_WINDOWS_ISO'||key.startsWith('WINDOWS_'))return t('Windows preparation rejected the image layout, filenames or boot files. Use a complete official ISO for the target PC and open details.','رفض تجهيز Windows تخطيط الصورة أو أسماء الملفات أو ملفات الإقلاع. استخدم ISO رسمية كاملة للحاسوب المطلوب وافتح التفاصيل.');if(key.startsWith('VENTOY_'))return pair(ERRORS.VENTOY_PACKAGE);return t('The tool could not finish. Open details for the exact error; USB access, file permissions, space and source-format failures have different causes.','لم تستطع الأداة الإكمال. افتح التفاصيل للخطأ الدقيق؛ فشل وصول USB وأذونات الملفات والمساحة وصيغة المصدر أسباب مختلفة.');}
function resultText(raw){if(raw.startsWith('FORMAT_OK '))return t('Format and metadata verification complete: ','اكتملت التهيئة والتحقق من البيانات الوصفية: ')+raw.slice(10);if(raw.startsWith('EXTRACTED '))return t('ZIP extracted into a new folder. Expanded size: ','استُخرج ZIP في مجلد جديد. الحجم بعد الاستخراج: ')+bytes(Number(raw.split(' ')[1]));if(RESULTS[raw])return pair(RESULTS[raw]);if(raw.startsWith('COPIED '))return t('Files copied: ','الملفات المنسوخة: ')+raw.split(' ')[1];if(raw.startsWith('READ_MIB '))return t('Sequential read: ','سرعة القراءة التسلسلية: ')+raw.split(' ')[1]+' MiB/s';return raw;}
function renderZipSelection(){const list=state.zipInputs||[];const sig=JSON.stringify(list);if(sig===zipSignature&&$('zip-selection').innerHTML)return;zipSignature=sig;$('zip-selection').innerHTML=`<p>${t('Selected files','الملفات المحددة')}: ${list.length}</p>`+list.map((name,i)=>`<div class="row-card"><span class="copy">${esc(name)}</span>${button('removeZipInput',t('Remove','إزالة'),'secondary',`data-id="${i}"`)}</div>`).join('');}
function placeToolJob(){
 const inTool=modal?.kind==='tool'&&modal.id===toolJobOwner;
 $('jobpanel').hidden=!!inTool;
 if(!inTool)return;
 const host=$('tool-job');if(!host)return;
 const content=toolPending?(state.error?`<div class="notice red">${t('Last reported error: ','آخر خطأ مسجل: ')}${esc(state.displayError||errorText(state.error))}</div>`:`<p class="notice">${t('Waiting for confirmation or task start…','انتظار التأكيد أو بدء المهمة…')}</p>`):$('jobpanel').innerHTML;
 let preview='';if(!toolPending&&!state.running&&(state.result||state.error)){
  preview=`<div class="result">${esc(state.error?(state.displayError||errorText(state.error)):(state.displayResult||resultText(state.result)))}</div>`;
  if(state.job==='wimList'&&!state.error){const paths=state.result.split('\n').map(x=>x.trim()).filter(x=>x.startsWith('/')&&x!=='/');preview+=paths.slice(0,200).map(path=>button('chooseWimPath',esc(path),'secondary wide',`data-path="${esc(path)}"`)).join('');}
 }
 host.innerHTML=content+preview;
 for(const node of Array.prototype.slice.call(document.querySelectorAll('#sheetbody input, #sheetbody select, #sheetbody button'))){const action=node.dataset?.action;if(['close','cancel','details','toggleHelp'].includes(action))continue;if(state.running){if(!node.hasAttribute('data-run-disabled'))node.setAttribute('data-run-disabled',node.disabled?'1':'0');node.disabled=true;}else if(node.hasAttribute('data-run-disabled')){node.disabled=node.getAttribute('data-run-disabled')==='1';node.removeAttribute('data-run-disabled');}}
}
let jobSignature='';
function ioText(io){if(!io)return '';const op={read:['Reading USB','قراءة USB'],write:['Writing USB','كتابة USB'],sync:['Syncing USB','مزامنة USB']};return `<p class="io-details">${t('USB read (includes verification)','قراءة USB (تشمل التحقق)')}: ${bytes(io.readBytes||0)} · ${t('USB written','كتابة USB')}: ${bytes(io.writeBytes||0)}<br>${t('Completed read / write requests','طلبات القراءة / الكتابة المكتملة')}: ${Number(io.reads||0)} / ${Number(io.writes||0)}${io.operation?' · '+pair(op[io.operation]||['USB request','طلب USB'])+' · '+Math.floor((io.activeMs||0)/1000)+' '+t('s','ث'):''}</p>`;}
function renderJob(){
    const signature=JSON.stringify([state.running,state.status,state.job,state.error,state.result,state.displayResult,state.displayError,Math.floor(state.done/65536),state.total,state.displayPhase,state.formatOptions,state.elapsedSeconds,state.cancelRequested,state.io,ar]);if(signature===jobSignature){placeToolJob();return;}jobSignature=signature;
    if(!state.running&&!state.error&&!state.result){$('jobpanel').innerHTML='';placeToolJob();return;}
    const pct=state.total>0?Math.min(100,100*state.done/state.total):0;
    $('jobpanel').innerHTML=state.running?`<article class="jobbox"><div class="toprow"><strong>${pair(JOB_NAMES[state.job]||[state.job,state.job])}</strong><button data-action="cancel" ${state.cancelRequested?'disabled':''}>${state.cancelRequested?t('Stopping…','جارٍ الإيقاف…'):t('Cancel','إلغاء')}</button></div><div class="progress-track ${state.total>0?'':'indeterminate'}" role="progressbar" aria-label="${t('Task progress','تقدم المهمة')}" ${state.total>0?`aria-valuenow="${pct.toFixed(0)}" aria-valuemin="0" aria-valuemax="100"`:`aria-valuetext="${t('Working; percentage unavailable','جارٍ العمل؛ النسبة غير متاحة')}"`}><div class="progress-fill" style="width:${state.total>0?pct:33}%"></div></div><p>${state.cancelRequested?t('Waiting for the current request to finish. Keep the drive connected.','انتظار انتهاء الطلب الحالي. أبقِ الوحدة متصلة.'):state.total>0?(state.job==='format'?t('Current stage: ','المرحلة الحالية: ')+pct.toFixed(0)+'%':`${pct.toFixed(0)}% · ${bytes(state.done)} / ${bytes(state.total)}`):t('Working — percentage unavailable','جارٍ العمل — النسبة غير متاحة')}${state.displayPhase?' · '+esc(state.displayPhase):''}</p><p>${t('Elapsed','الوقت المنقضي')}: ${Math.max(0,Number(state.elapsedSeconds||0))} ${t('s','ث')} · ${t('Keep USB connected','أبقِ USB متصلاً')}</p>${ioText(state.io)}${state.io&&state.io.idleMs>=30000?`<p class="notice">${t('No USB disk request has finished in the last ','لم ينتهِ طلب لقرص USB خلال آخر ')}${Math.floor(state.io.idleMs/1000)} ${t('seconds. Waiting for the formatter or device; this alone does not identify the cause.','ثانية. انتظار المحرك أو الجهاز؛ هذا وحده لا يحدد السبب.')}</p>`:''}</article>`:`<article class="jobbox ${state.error||state.result.includes('SHA-256 MISMATCH')?'error':''}"><div class="toprow"><strong>${state.error?t('Please check','يرجى المراجعة'):state.result.includes('SHA-256 MISMATCH')?t('Checksum mismatch','بصمة غير متطابقة'):t('Task complete','اكتملت المهمة')}</strong><button data-action="dismiss">×</button></div><p>${esc(state.error?errorText(state.error):state.result.includes('SHA-256 MISMATCH')?t('The SHA-256 does not match the expected value. Check the source file before using it.','لا تطابق SHA-256 القيمة المتوقعة. تحقق من الملف المصدر قبل استخدامه.'):state.result.includes('SHA-256 MATCH')?t('The SHA-256 matches your expected value.','تطابق SHA-256 القيمة التي أدخلتها.'):state.result.startsWith('SHA-256')?t('Checksum ready. Open details to compare.','البصمة جاهزة. افتح التفاصيل للمقارنة.'):state.result.includes('\n')?t('Results are ready to view.','النتائج جاهزة للعرض.'):(state.displayResult||resultText(state.result)))}</p><button data-action="details">${t('View details','عرض التفاصيل')}</button></article>`;
    placeToolJob();
}
function details(h){showSheet(`<span class="eyebrow">${t('OPERATION DETAILS','تفاصيل العملية')}</span><h2 id="sheet-title">${pair(JOB_NAMES[h.job]||[h.job||'USB',h.job||'USB'])}</h2>${ioText(h.io)}${h.displayPhase?`<p>${esc(h.displayPhase)} · ${esc(h.formatOptions||'')}</p>`:''}${h.error?`<div class="notice red">${esc(errorText(h.error))}</div><div class="result">${esc(h.displayError||h.error)}</div>`:`<p>${esc(h.result.includes('\n')?t('Diagnostic output is shown below. Numeric values and file names are preserved.','المخرجات التشخيصية أدناه. حُفظت القيم العددية وأسماء الملفات.'):(h.displayResult||resultText(h.result)))}</p><div class="result">${esc(h.displayResult||h.result)}</div>`}<div class="actions">${button('guide',t('Troubleshooting guide','دليل حل المشكلات'),'secondary wide','data-id="trouble"')}${button('close',t('Close','إغلاق'),'primary wide')}</div>`,{kind:'details'});}
function poll(){if(!native)return;try{
    const raw=Native.state();if(raw===lastState)return;lastState=raw;const prev=state;state=JSON.parse(raw);if(state.running||JSON.stringify([state.running,state.status,state.job,state.result,state.error,state.history?.[0]?.time||0])!==toolBefore)toolPending=false;renderJob();
    if(tab==='home'&&JSON.stringify([prev.devices,prev.selected])!==JSON.stringify([state.devices,state.selected]))$('devicehome').innerHTML=deviceCard();
    if(false&&(prev.folder!==state.folder||JSON.stringify(prev.files)!==JSON.stringify(state.files)))renderFiles();
    if(tab==='activity'&&JSON.stringify(prev.history)!==JSON.stringify(state.history))renderActivity();
    if(modal?.kind==='tool'){
        if(modal.id==='createzip')renderZipSelection();
        if($('source-name'))$('source-name').textContent=state.image||t('No file selected','لم يُحدد ملف');if($('source-size'))$('source-size').textContent=state.image?bytes(state.imageSize):t('Choose a file from phone storage','اختر ملفاً من تخزين الهاتف');if($('target-detail'))$('target-detail').innerHTML=targetText();
    }
}catch(e){toast(t('Could not read app state. Reopen the app.','تعذرت قراءة حالة التطبيق. أعد فتحه.'));}}
function toast(text){$('toast').textContent=text;$('toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').style.display='none',4000);}
function go(id){closeSheet();tab=['tools','files'].includes(id)?'home':id;if(tab==='home')filter='all';render();if(tab==='files'&&state.tree)call('list','');window.scrollTo(0,0);}
function appBack(){if(choiceSource){closeChoices();return;}if(modal)closeSheet();else if(tab==='files'&&fileTrail.length){call('list',fileTrail.pop());}else if(tab!=='home')go('home');else call('close');}window.appBack=appBack;
document.addEventListener('change',e=>{if(e.target.id==='filesystem')refreshFormat();else if(e.target.id==='cluster-size')customCluster();else if(e.target.id==='burn-mode'){burnMode=['ventoy','persistent'].includes(e.target.value)?e.target.value:'raw';tool('write');}else if(e.target.id==='persistence-preset'&&e.target.value!=='custom')$('persistence-label').value=e.target.value;enhanceChoices();});
document.addEventListener('input',e=>{if(e.target.id==='choice-search'){renderChoices();return;}if(e.target.id==='learn-search'){renderLearnQuestions();return;}if(e.target.id==='search'){query=e.target.value;renderToolResults();}});
document.addEventListener('click',e=>{
    const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,id=b.dataset.id,uri=b.dataset.uri;
    if(a==='choices')openChoices(id);
    else if(a==='chooseOption')chooseOption(id);
    else if(a==='closeChoices')closeChoices();
    else if(a==='about')go('about');
    else if(a==='clearHistory')call('clearHistory');
    else if(a==='addZipFiles')call('addZipFiles');
    else if(a==='removeZipInput')call('removeZipInput',Number(id));
    else if(a==='createSelectedZip')call('createSelectedZip');
    else if(a==='splitWim')call('splitWim',Number($('wim-part-size').value));
    else if(a==='chooseWimPath'){$('wim-path').value=e.target.closest('[data-path]').dataset.path;$('wim-path').focus();}
    else if(a==='forgetFolder')call('forgetFolder');
    else if(a==='tab')go(id);
    else if(a==='pin')togglePin(id);
    else if(a==='tool')tool(id);
    else if(a==='guide')guide(id);
    else if(a==='learnQuestion')learnQuestion(id);
    else if(a==='officialDownload')call('officialDownload',id);
    else if(a==='imageTool'){call('imageTool',id);}
    else if(a==='convertTable'){call('convertTable',$('convert-target').value);}
    else if(a==='fsUsb'){call('fsUsb',id==='extract',Number($('fsimage-partition').value),Number($('fsimage-limit').value));}
    else if(a==='fsImage'){call('fsImage',id==='extract',Number($('fsimage-partition').value),Number($('fsimage-limit').value));}
    else if(a==='chdTool'){const mode=$('chd-mode').value;if(mode==='stored512'||mode==='stored2048')call('createChd',mode==='stored512'?512:2048,Number($('chd-limit').value));else call('chdTool',Number($('chd-limit').value));}
    else if(a==='partitionMetadata'){call('partitionMetadata',id,Number($('partition-number').value),String($('partition-name').value));}
    else if(a==='readMap'){call('readMap',id);}
    else if(a==='wimTree'){call('wimTree',id==='extract',Number($('tree-index').value),Number($('archive-limit').value),String($('tree-root').value));}
    else if(a==='usbExtreme'){call('usbExtreme',id==='inspect',String($('ul-title').value),String($('ul-media').value));}
    else if(a==='archiveTool'){const password=$('archive-password').value||'';$('archive-password').value='';if(password)call('archivePassword',id==='extract',Number($('archive-limit').value),password);else call('archiveTool',id==='extract',Number($('archive-limit').value));}
    else if(a==='fatImage'){call('fatImage',id==='fatExtract',Number($('fat-partition').value));}
    else if(a==='filesystemTool'){call('filesystemTool',id==='repair',Number($('fs-partition').value));}
    else if(a==='consoleSplit'){call('consoleSplit',String($('console-kind').value),Number($('console-size').value),String($('console-name').value));}
    else if(a==='consoleJoin'){call('consoleJoin');}
    else if(a==='convertImage'){call('convertImage',String($('convert-mode').value),Number($('convert-limit').value));}
    else if(a==='writePersistent')startPersistence(true);
    else if(a==='createPersistence')startPersistence();
    else if(a==='benchTool'){if(id==='persistence'){startPersistence();return;}if(id==='fileBenchmark')call('benchTool',id,Number($('bench-size').value),'','');else if(id==='persistence')call('benchTool',id,Number($('persistence-size').value),$('persistence-label').value,$('persistence-iso').value);else call('benchTool',id,Number($('wim-index').value),String($('wim-path').value||''),'');}
    else if(a==='close')closeSheet();
    else if(a==='devices'||a==='refreshdevices'){poll();devices();}
    else if(a==='select'){call('select',uri);closeSheet();}
    else if(a==='filter'){filter=id;render();}
    else if(a==='group'){openGroups[id]=!openGroups[id];renderToolResults();const head=$('group-'+id);if(head)head.focus();}
    else if(a==='image')call('pickImage');
    else if(a==='folder'){call('pickFolder');}
    else if(a==='copy')call('copy');
    else if(a==='browse'){go('files');call('list','');fileTrail=[];}
    else if(a==='enter'){fileTrail.push(state.folder);call('list',uri);}
    else if(a==='up'){call('list',fileTrail.length?fileTrail.pop():'');}
    else if(['rename','delete','filehash'].includes(a))call('file',a==='filehash'?'hash':a,uri);
    else if(a==='recipe'){const r=RECIPES[Number(id)];if(r){tool(r.tool);if(r.fs&&$('filesystem')){$('filesystem').value=r.fs;refreshFormat();}}}
    else if(a==='checksums'){call('checksums',String($('expected-hash').value||'').trim());}
    else if(a==='authorizeClone'){call('authorizeClone',$('clone-target').value);}
    else if(a==='clonePhone'){call('clonePhone');}
    else if(a==='cloneUsb'){call('cloneUsb',$('clone-target').value);}
    else if(a==='workshop'){call('workshop',id,id==='split'?Number($('part-size').value)*1048576:268435456);}
    else if(a==='run'){
        if(state.running){toast(pair(ERRORS.JOB_BUSY));return;}
        if(id==='write'&&burnMode!=='raw'){toast(t('Switch to direct image writing first.','انتقل أولاً إلى كتابة الصورة مباشرة.'));return;}
        const label=$('volume-label')?.value||'USBWORK',rawCluster=$('cluster-size')?.value||'0',cluster=rawCluster==='custom'?Number($('custom-cluster-bytes').value)/512:Number(rawCluster);
        if(rawCluster==='custom'&&(!isFinite(cluster)||cluster<1||Math.floor(cluster)!==cluster||(cluster&(cluster-1))!==0)){toast(t('Custom allocation must be a power of two and a multiple of 512 bytes.','يجب أن يكون التخصيص قوة للعدد 2 ومضاعفاً لـ512 بايت.'));return;}
        const fs=$('filesystem')?.value||'fat32',table=$('partition-table')?.value||'mbr';
        if(id==='format'&&['fat12','fat16','fat32'].includes(fs)&&(!label.trim()||!/^[A-Za-z0-9 _-]{1,11}$/.test(label))){toast(pair(ERRORS.FAT_LABEL));return;}
        call('usbAdvanced',id==='capacity'&&$('capacity-passes').value==='3'?'capacityDeep':id,label,cluster,fs,table);
    }else if(['backup','hash','zip','extract'].includes(a)){call(a);}
    else if(a==='cancel'){if(confirm(t('Cancel this task? Writes already made cannot be undone, and the result can be incomplete.','هل تريد إلغاء المهمة؟ لا يمكن التراجع عن الكتابات السابقة وقد تكون النتيجة غير مكتملة.')))call('cancel');}
    else if(a==='dismiss')call('dismiss');
    else if(a==='details')details(state);
    else if(a==='history')details(state.history[Number(id)]);
    else if(a==='roadmap'){const r=ROADMAP[Number(id)];showSheet(`<span class="badge plan">${t('PLANNED · NOT AVAILABLE','مخطط لها · غير متاحة')}</span><h2 id="sheet-title">${esc(pair(r.name))}</h2><p>${esc(pair(r.body))}</p><div class="notice info">${t('This is an honest development roadmap. No disk operation will run from this screen.','هذه خطة تطوير واضحة. لن تُشغّل هذه الشاشة أي عملية على القرص.')}</div>${button('close',t('Close','إغلاق'),'secondary wide')}`,{kind:'roadmap',id});}
});
$('lang').addEventListener('click',()=>{ar=!ar;try{localStorage.setItem('language',ar?'ar':'en');}catch(e){}call('language',ar);closeSheet();jobSignature='';render();});
$('overlay').addEventListener('click',e=>{if(e.target===$('overlay'))closeSheet();});
document.addEventListener('keydown',e=>{if(e.key==='Escape')appBack();if(e.key==='Tab'&&modal&&!choiceSource){const items=[...$('overlay').querySelectorAll('button,input,select')].filter(x=>!x.disabled);if(items.length){let first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault();}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault();}}}});
if(native){try{Native.language(ar);}catch(e){}}
render();setTimeout(poll,50);setInterval(poll,900);

function renderAbout(){
    $('content').innerHTML=`<h1 class="page-title">${t('Your data stays yours','بياناتك تبقى لك')}</h1><p>${t('USB Workbench 0.16.1 · Offline USB tools','ورشة USB 0.16.1 · أدوات USB دون إنترنت')}</p><section class="notice info">${t('No ads, account, analytics or automatic uploads. This build has no internet permission. File processing happens on your device. A storage provider may transfer files when you choose a cloud location. Choose local storage to avoid that data usage.','لا إعلانات أو حسابات أو تحليلات أو رفع تلقائي. لا يملك هذا الإصدار إذن الإنترنت. تتم معالجة الملفات على جهازك. قد ينقل مزود التخزين الملفات إذا اخترت موقعاً سحابياً؛ اختر تخزيناً محلياً لتجنب استهلاك تلك البيانات.')}</section><h2>${t('Privacy policy','سياسة الخصوصية')}</h2><p>${t('USB access is used only for tasks you request. Android’s folder and file picker limits file access to locations you authorize. Notifications and a wake lock keep long tasks visible and running. We do not receive your files, device details or task results.','يُستخدم وصول USB للمهام التي تطلبها فقط. يحصر منتقي ملفات أندرويد الوصول في المواقع التي تسمح بها. تُستخدم الإشعارات وقفل الاستيقاظ لإظهار المهام الطويلة ومتابعتها. لا نستقبل ملفاتك أو تفاصيل جهازك أو نتائج مهامك.')}</p><p>${t('The app stores your language, pinned tools, folder permission and the last 20 task results locally. Results can include filenames, checksums, USB serials and partition identifiers. Clear history below; revoke saved folder access below or remove app data through Android settings. Backups, archives, split/join outputs and reports remain where you saved them and must be managed separately.','يحفظ التطبيق لغتك والأدوات المثبتة وإذن المجلد وآخر 20 نتيجة مهمة محلياً. قد تشمل النتائج أسماء ملفات وبصماتها وأرقام USB ومعرفات الأقسام. امسح السجل أدناه، وألغِ وصول المجلد أدناه أو احذف بيانات التطبيق من إعدادات أندرويد. تبقى النسخ والأرشيفات ونواتج التقسيم والدمج والتقارير حيث حفظتها وتُدار بشكل منفصل.')}</p><div class="file-actions">${button('workshop',t('Export native source & licenses','تصدير المصدر الأصلي والتراخيص'),'secondary','data-id="sources"')}${button('clearHistory',t('Clear task history','مسح سجل المهام'),'secondary')}${button('forgetFolder',t('Forget saved file/folder access','إلغاء الوصول المحفوظ للملفات والمجلدات'),'secondary')}</div><div class="divider"></div><h2>${t('Safety and limitations','السلامة والحدود')}</h2><p>${t('Destructive tasks erase data and cannot be undone. Keep backups. This release needs validation on your specific USB hardware. Some advanced engines are still planned and clearly marked unavailable on Home. No games, firmware or operating systems are bundled. USB Workbench is independent of Ventoy and MixApplications.','المهام المدمرة تمحو البيانات ولا يمكن التراجع عنها. احتفظ بنسخ احتياطية. يحتاج الإصدار اختباراً على جهاز USB الخاص بك. بعض المحركات المتقدمة مخطط لها وموضحة كغير متاحة في الرئيسية. لا يتضمن التطبيق ألعاباً أو برمجيات أجهزة أو أنظمة تشغيل. ورشة USB مستقل عن Ventoy وMixApplications.')}</p><p class="footnote">${t('Privacy policy effective: 2 November 2026. Future SDKs or ads require an updated disclosure before release.','تاريخ سريان سياسة الخصوصية: 2 نوفمبر 2026. أي مكتبات جديدة أو إعلانات تتطلب تحديث الإفصاح قبل النشر.')}</p>${button('tab',t('Back to Home','العودة للرئيسية'),'primary wide','data-id="home"')}`;
}


// The original selects remain the value source; Android's native popup is replaced.
let choiceSource=null,choiceFocus=null;
function syncChoice(select){const trigger=$('pick-'+select.id);if(!trigger)return;const option=select.options[select.selectedIndex];trigger.innerHTML=`<span>${esc(option?option.textContent:'')}</span><span aria-hidden="true">⌄</span>`;trigger.disabled=select.disabled;}
function enhanceChoices(){Array.prototype.forEach.call(document.querySelectorAll('#sheetbody select'),select=>{if(!select.id)return;let trigger=$('pick-'+select.id);if(!trigger){select.className+=' choice-source';select.tabIndex=-1;select.setAttribute('aria-hidden','true');trigger=document.createElement('button');trigger.id='pick-'+select.id;trigger.type='button';trigger.className='choice-trigger';trigger.dataset.action='choices';trigger.dataset.id=select.id;trigger.setAttribute('aria-haspopup','dialog');trigger.setAttribute('aria-controls','choiceoverlay');trigger.setAttribute('aria-expanded','false');const label=document.querySelector('label[for="'+select.id+'"]');if(label){label.id='label-'+select.id;trigger.setAttribute('aria-labelledby',label.id+' '+trigger.id);}select.parentNode.insertBefore(trigger,select.nextSibling);}syncChoice(select);});}
function openChoices(id){const select=$(id);if(!select||select.disabled||!select.options)return;choiceSource=select;choiceFocus=$('pick-'+id);if(choiceFocus)choiceFocus.setAttribute('aria-expanded','true');const label=document.querySelector('label[for="'+id+'"]');$('choice-title').textContent=label?label.textContent:t('Choose an option','اختر خياراً');$('choice-search').value='';$('choice-search').placeholder=t('Search options','ابحث في الخيارات');$('choice-search').hidden=select.options.length<8;$('choice-close').textContent=t('Done','تم');$('choiceoverlay').hidden=false;renderChoices();const selected=document.querySelector('#choice-list [aria-selected="true"]');(selected||$('choice-close')).focus();}
function renderChoices(){if(!choiceSource)return;const q=learningSearch($('choice-search').value);let html='';Array.prototype.forEach.call(choiceSource.options,(option,index)=>{if(q&&!learningSearch(option.textContent).includes(q))return;const disabled=option.disabled||(option.parentNode&&option.parentNode.disabled);html+=`<button type="button" class="choice-option ${option.selected?'selected':''}" role="option" aria-selected="${option.selected}" data-action="chooseOption" data-id="${index}" ${disabled?'disabled':''}><span>${esc(option.textContent)}</span><span class="choice-mark" aria-hidden="true">${option.selected?'✓':''}</span></button>`;});$('choice-list').innerHTML=html||`<p>${t('No matching options','لا توجد خيارات مطابقة')}</p>`;}
function chooseOption(index){if(!choiceSource)return;const select=choiceSource,option=select.options[Number(index)];if(!option||option.disabled||(option.parentNode&&option.parentNode.disabled))return;const changed=select.selectedIndex!==Number(index);select.selectedIndex=Number(index);closeChoices();syncChoice(select);if(changed){const event=document.createEvent('HTMLEvents');event.initEvent('change',true,false);select.dispatchEvent(event);enhanceChoices();}}
function closeChoices(restore=true){if(typeof choiceSource==='undefined'||!choiceSource)return;const focus=choiceFocus;choiceSource=null;choiceFocus=null;$('choiceoverlay').hidden=true;if(focus){focus.setAttribute('aria-expanded','false');if(restore)focus.focus();}}
document.addEventListener('keydown',e=>{if(!choiceSource)return;if(e.key==='Escape'||e.keyCode===27){e.preventDefault();closeChoices();return;}const buttons=Array.prototype.slice.call(document.querySelectorAll('#choiceoverlay button:not([disabled]),#choiceoverlay input:not([hidden])'));const at=buttons.indexOf(document.activeElement);if(e.key==='Tab'||e.keyCode===9){if(e.shiftKey&&at<=0){e.preventDefault();buttons[buttons.length-1].focus();}else if(!e.shiftKey&&at===buttons.length-1){e.preventDefault();buttons[0].focus();}}else if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();buttons[(at+(e.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length].focus();}});

$('choiceoverlay').addEventListener('click',e=>{if(e.target===$('choiceoverlay'))closeChoices();});

